-- Lane A figures for ap_statistics: generated by build_load_sql.py, do not hand-edit.
-- 1 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('categorical_bars', 'Categorical and binned bars', 'Bar chart, histogram, side-by-side, segmented and mosaic, as five modes of one rectangle geometry. Separated bars for a categorical variable, contiguous bars for a quantitative one, and mosaic bar widths proportional to the category totals.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-gap-histogram', 'ap_statistics', 'categorical_bars', 'A gap in a histogram', 'Gap in a histogram', 'One interval between two values holds no observations', 'Ages of 38 customers in ten-year bins; the 40 to 50 bin is empty, which is a gap.', 'A histogram of the ages of 38 customers in six bins of ten years from 10 to 70. The bar heights are 7, 14, 9, 0, 5 and 3 customers, so the bin from 40 to 50 years has no bar: no customer in the data is between those two ages. That empty interval between two filled ones is a gap. Illustrative data.', 'age of a customer (years)', 'number of customers', 'A gap is an interval between two values with no observed data, so the bars on either side of it are separated by an empty bin.', true, null, '["Horizontal axis (values of the variable)", "Vertical axis (frequency)", "Gap: an interval with no observed data"]'::jsonb, '{"mode": "histogram", "bin_edges": [10, 20, 30, 40, 50, 60, 70], "counts": [7, 14, 9, 0, 5, 3], "measure": {"bin": 3, "label": "gap: no data"}}'::jsonb, null, null, 'published', 'cramapple-authored; batch=stats-next2-figures-2026-10-15', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-gap-histogram', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'vocabulary'
   and e.title = 'Gap' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('stats-gap-histogram') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('stats-gap-histogram');
  if v_n <> 1 then
    raise exception 'expected 1 figures, found %', v_n;
  end if;
end $$;

commit;
